def total_pages(item_count, per_page):
    """How many pages are needed to show item_count items."""
    return item_count // per_page


def page_items(items, page, per_page):
    """The items on a 1-based page; an empty list for a page that does not exist."""
    if page < 1 or page > total_pages(len(items), per_page):
        return []
    start = (page - 1) * per_page
    return items[start : start + per_page]

