import unittest

from api import list_response
from pagination import total_pages

ITEMS = list(range(30))


class Regression(unittest.TestCase):
    def test_an_exact_multiple_has_no_extra_empty_page(self):
        self.assertEqual(total_pages(30, 10), 3)
        self.assertEqual(list_response(ITEMS, page=4, per_page=10)["items"], [])

    def test_no_items_means_no_pages(self):
        self.assertEqual(total_pages(0, 10), 0)

    def test_one_item_is_one_page(self):
        self.assertEqual(total_pages(1, 10), 1)

    def test_pages_before_the_first_are_empty(self):
        self.assertEqual(list_response(ITEMS, page=0, per_page=10)["items"], [])

    def test_a_middle_page_is_full(self):
        self.assertEqual(list_response(ITEMS, page=2, per_page=10)["items"], list(range(10, 20)))

